16|pub(crate) fn request(operation: &str, actor: &str, session: &str, genesis: &str,
17|    kind: &str, target: &str, body: Value) -> Result<NativeCreationRequest> {
18|    ensure!(body.is_object() && body.get("name").is_none(), "native name is server assigned");
19|    let plugin = match kind { "identity" => "identity_sled", "project" => "project", "incus" => "incus",
20|        _ => anyhow::bail!("unknown native owner") };
21|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
22|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
23|    let request_json = serde_json::to_string(&body)?;
24|    let request_digest = format!("{:x}", Sha256::digest(request_json.as_bytes()));
25|    Ok(NativeCreationRequest { operation_id: operation.into(), actor_id: actor.into(),
26|        caller_session: session.into(), caller_genesis: genesis.into(), owner_kind: kind.into(),
27|        logical_target: target.into(), schema_hash: pin.schema_hash, request_digest, request_json })
28|}
29|
30|async fn admit(engine: &MutationEngine, request: &NativeCreationRequest) -> Result<()> {
31|    let (plugin, method, capability) = match request.owner_kind.as_str() {
32|        "identity" => ("identity_sled", "prepare_container", "identity_sled.write"),
33|        "project" => ("project", "create", "project.create"),
34|        "incus" => ("incus", "create_instance", "cap.service.incus.instance.create@v1"),
35|        _ => anyhow::bail!("unknown native owner"),
36|    };
37|    crate::method_contract_admission::admit_compiled_method(plugin, method, Some(capability))?;
38|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
39|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
40|    ensure!(pin.schema_hash == request.schema_hash, "native creation seal changed; explicit reconciliation required");
41|    ensure!(crate::interceptor::load_capability_grants(&request.actor_id).contains(capability),
42|        "native creation requires current exact-principal grant");
43|    let current = engine.session_context_for_actor(&request.actor_id).await
44|        .context("native creation caller session missing")?;
45|    ensure!(current.session_id == request.caller_session && current.genesis_hex == request.caller_genesis,
46|        "native creation caller session changed");
47|    Ok(())
48|}
