130|pub(crate) async fn dispatch(engine: &MutationEngine, method: &str, args: &Value,
131|    actor: &str, session: Option<&str>, genesis: Option<&str>) -> Result<Value> {
132|    let session = session.context("native creation requires verified session")?.to_owned();
133|    let genesis = genesis.context("native creation requires verified genesis")?.to_owned();
134|    let engine = engine.clone();
135|    let method = method.to_owned();
136|    let args = args.clone();
137|    let actor = actor.to_owned();
138|    tokio::spawn(async move {
139|        let _host = engine.lock_host_observation().await;
140|        let (record, replayed) = if method == "create_instance" {
141|            let input: incus::CreateInstanceInput = serde_json::from_value(args)?;
142|            let body = incus::native_creation_body(&input)?;
143|            let request = request(&input.operation_id, &actor, &session, &genesis,
144|                "incus", &input.operation_id, body)?;
145|            create_locked(&engine, request).await?
146|        } else {
147|            let input: incus::ReconcileNativeCreationInput = serde_json::from_value(args)?;
148|            let record = records(&engine).await?.into_iter()
149|                .find(|r| r.request.operation_id == input.operation_id)
150|                .context("native creation operation not found")?;
151|            ensure!(record.request.owner_kind == "incus" && record.request.actor_id == actor
152|                && record.request.caller_session == session && record.request.caller_genesis == genesis,
153|                "native creation operation belongs to another owner");
154|            (reconcile_locked(&engine, record).await?, true)
155|        };
156|        Ok(json!({"name":record.name,"operation_id":record.request.operation_id,
157|            "native_uuid":record.native_uuid,"phase":record.phase,"replayed":replayed,
158|            "created":true,"changes":[]}))
159|    }).await.context("native creation owner failed; reconcile the same operation")?
